import { React, useState, useEffect, Fragment, useCallback } from "react"
import axios from "axios"
import { trackPromise } from "react-promise-tracker"
import ShowSpinner from "./components/ShowSpinner"


const ApprovalCenter = props => {
  const { currentRacf, setDisplayAlert, superUserMode, convert2MMDDYY, convertToLocal, sharePointPath } = props

  const [pendingList, setPendingList] = useState([])

  const [checkedState, setCheckedState] = useState([])
 
  const gotoSharePoint = (ref, folder, sharePointID) => {  
    // sharePoint variables : year, sharePointPath, racf and office

    const year =  ref.substring(3,7) // get the year via the reference no.      
    
    const url = "https://macysinc.sharepoint.com/sites/MMGOverseas/".concat(sharePointPath, "/Forms/AllItems.aspx?id=%2Fsites%2FMMGOverseas%2F", sharePointPath, "%2F", folder, "%2F", "&FilterType1=Text&viewid=720379f5-eb23-410f-81d1-f4e43a1a1cab&FilterField1=SharePointID&FilterValue1=", sharePointID, "&dt=", new Date().getTime())
       

    const newWindow = window.open(url, "_blank", "noopener,noreferrer")
    if (newWindow) newWindow.opener = null
  }
  
  const refreshApprove = useCallback(() => {

    trackPromise(
      
      axios({
        url: "/eleave/api/listapprove",
        method: "POST",
        headers: {
          "Content-type": "application/json",
          api: "yes"
        },
        data: JSON.stringify({ racf: currentRacf })
        //data: JSON.stringify({"year": Number(year), "racf":   userProfile.racf} )
      })
        .then(response => response.data)
        .then(response => {
          const new_pendingList = response["result"]
          setPendingList(new_pendingList)          
          //console.log(new_pendingList)          
          const new_checkState = new Array(new_pendingList.length).fill(false)
          setCheckedState(new_checkState)
        })
        .catch(error => {
          setDisplayAlert({ message: error.response.data.error_message, position: 4, timeout: 3000, color: "alert__red" })
          //console.log(error)
        }),
      "approvalCenter"
    )

    return () => {
      //setUserList(null) // This worked for me
    }

  
  }, [currentRacf,setDisplayAlert])
 

  useEffect(() => {        
    refreshApprove();
  }, [currentRacf, refreshApprove])

  
  // Please note that below function code appears in Approval Center and Cancel Leave in a slightly different way   
  function checkSelection(pendingList, maxSelect) {

    let num_selected = 0 
    let first_selected = 0 
    const new_pendingList = [...pendingList]    
    let ref_no = "" 

    for (let i = 0; i < checkedState.length; i += 1) {
      if (checkedState[i] === true) {
        num_selected++
        if (first_selected === 0) {
            first_selected = num_selected // this is to note the first selected application 
            ref_no = new_pendingList[i]["ref_no"] 
        }     
        if (num_selected > maxSelect) {
          setDisplayAlert({ message: "select one application at a time please !", position: 3, timeout: 4000, color: "alert__red" } )     
          handleClearAll()           
          return null
        }
      }
    }  
    
    // check if any has been selected
    if (first_selected === 0) {
      setDisplayAlert({ message: "No application has been selected !", position: 3, timeout: 4000, color: "alert__red" } )    
      return null        
    }

    return { ref_no : ref_no, pendingList : pendingList}

  }

 
  const handleOnChange = position => {    
    const updatedCheckedState = checkedState.map((item, index) => (index === position ? !item : item))
    setCheckedState(updatedCheckedState)
  }


  const handleApprove = async () => {

    
    let new_pendingList = [...pendingList]     
    
    // max selection is virtually no limit so in this case so pass 9999 
    const checkSelectionResult = checkSelection(pendingList, 9999 )

    if ( checkSelectionResult=== null) {
        return null
    }

    for (let i = 0; i < checkedState.length; i += 1) {
      if (checkedState[i] === true) {
        let options = {
          headers: {
            "Content-type": "application/json",
            api: "yes"
          }
        }
        //  please note currentRacf is the approver 
        let data = { refNo: new_pendingList[i]["ref_no"], otherRefNo: new_pendingList[i]["otherRefNo"], racf: currentRacf, action: "APPROVE", superUser: superUserMode, localTime: convertToLocal(Date.now()) }

        try {
          await trackPromise(axios.post("/eleave/api/changestatus", data, options), "changeStatus")
            .then(response => response.data)
            .then(response => {
              // refNo, racf, action - APPROVE, CANCEL,REJECT, false                   
              //console.log("Successufully updated", response)        
      
            })
            .catch(error => {
              //console.log('error from changestatus', error);
              setDisplayAlert({ message: error.response.data.error_message, position: 4, timeout: 3000, color: "alert__red" })
            })
        } catch (error) {
          setDisplayAlert({ message: error.response.data.error_message, position: 4, timeout: 5000, color: "alert__red" })
        }
      }
    }
    
    setPendingList(new_pendingList)
    handleClearAll()
    refreshApprove()
    return () => {
      //setUserProfile(null)   

    }
  }

  const handleReject = async () => {
       
    let new_pendingList = [...pendingList]     
    
    // max selection is virtually no limit so in this case so pass 9999 
    const checkSelectionResult = checkSelection(pendingList, 9999 )

    if ( checkSelectionResult=== null) {
        return null
    }

    
    for (let i = 0; i < checkedState.length; i += 1) {
      if (checkedState[i] === true) {
        let options = {
          headers: {
            "Content-type": "application/json",
            api: "yes"
          }
        }

        let data = { refNo: new_pendingList[i]["ref_no"], racf: currentRacf, action: "REJECT", superUser: superUserMode, localTime:  convertToLocal(Date.now())  }

        try {
          await trackPromise(axios.post("/eleave/api/changestatus", data, options), "changeStatus")
            .then(response => response.data)
            .then(response => {
              new_pendingList[i]["approvalStatus"] = "REJECT"
            })
            .catch(error => {
              console.log('error from changestatus', error);
              setDisplayAlert({ message: error.response.data.error_message, position: 4, timeout: 3000, color: "alert__red" })
            })
        } catch (error) {
          setDisplayAlert({ message: "Unexpected error", position: 4, timeout: 3000, color: "alert__red" })
        }
      }
    }
    setPendingList(new_pendingList)
    handleClearAll()
    refreshApprove()
    return () => {
      //setUserProfile(null)
    }
    
  }

  const handleSelectAll = () => {
    let allApprovalCheckboxes = document.getElementsByName("approval")
    for (var i = 0; i < allApprovalCheckboxes.length; i++) {
      allApprovalCheckboxes[i].checked = true
      checkedState[i] = true
    }
  }

  const handleClearAll = () => {
    let allApprovalCheckboxes = document.getElementsByName("approval")    
    for (var i = 0; i < allApprovalCheckboxes.length; i++) {
      allApprovalCheckboxes[i].checked = false
      checkedState[i] = false
    }
  }

  const getWeekday = (dateString) => {
    if (!dateString) return '';
    const date = new Date(dateString);
    // Returns full weekday name (e.g., "Monday", "Tuesday")
    return date.toLocaleDateString('en-US', { weekday: 'long' })
  }

  return (
    <Fragment>
      <div>
        <div>
          <div className="subHeading">Approval Center</div>
          
          <table id="approvalCenter_Table"> 
            <tbody>

              <tr className="approvalCenter_grid">
                <th>Select</th>                          
                <th>Applicant</th>
                <th>Type</th>
                <th>Status</th>              
                <th>Docs</th>
                <th>&nbsp;</th>
              </tr>                             
              
                  {pendingList.map((x, index) => (                    
                      <tr key={index} className="approvalCenter_grid">               
                          <td className="approvalCenter_input">
                            <input type="checkbox" name="approval" value={x.ref} onChange={() => handleOnChange(index)} />
                          </td>                          
                          <td>{x.staff}</td>
                          <td>{x.type}</td>
                          <td>{x.approvalStatus}</td>
                          <td>
                            {/* show document link to SharePoint when the leave is with medical cert */}
                            {x.type_id==="LVE04"?(                                                       
                            <i class="fa fa-file-text-o"  onClick={() => {gotoSharePoint(x.ref_no, x.racf, x.sharePointId)}}></i>
                            ): null}                            
                          </td>        
                          <td>                     
                                <div className="approvalCenterInner_grid">                               
                                      <div>Start</div>              
                                      <div>End</div>
                                      <div>Working Days</div>
                                      <div>OOO Days</div>
                                      <div>Balance</div>
                                </div>                               
                                
                                  {x.details.map((y, index2) => (
                                    <div key={index2} className="approvalCenterInner2_grid">
                                      
                                      {/* Start Date */}
                                      <div 
                                        className="tooltip-container" 
                                        data-weekday={getWeekday(y.startDate)} // Pass the weekday here
                                      >
                                        {convert2MMDDYY(y.startDate)}&nbsp;({y.startTime})
                                      </div>

                                      {/* End Date */}
                                      <div 
                                        className="tooltip-container" 
                                        data-weekday={getWeekday(y.endDate)}   // Pass the weekday here
                                      >
                                        {convert2MMDDYY(y.endDate)}&nbsp;({y.endTime})
                                      </div>

                                      <div>{y.workday}</div>
                                      <div>{y.calendarDay}</div>
                                      <div>{x.balance}</div>
                                    </div>
                                  ))}         
                          </td>    
                        </tr>                  
                  ))}
            </tbody>
          </table>   
          <ShowSpinner position={4} />
 
            <div className="approvalCenter">
              <button
                className="fa fa-dot-circle-o"
                onClick={() => {
                  handleSelectAll()
                }}
              >
                &nbsp;Select All
              </button>
              <button
                className="fa fa-circle-o"
                onClick={() => {
                  handleClearAll()
                }}
              >
                &nbsp;Clear All
              </button>
              <button
                className="fa fa-check"
                onClick={() => {
                  handleApprove()
                }}
              >
                &nbsp;Approve
              </button>
              <button
                className="fa fa-times"
                onClick={() => {
                  handleReject()
                }}
              >
                &nbsp;Reject
              </button>
            </div>
          </div>
        </div>
      
   
    </Fragment>
  )
}

export default ApprovalCenter
