import React, { Fragment, useState } from "react"
import axios from "axios"
import { trackPromise } from "react-promise-tracker"

const UploadForm = props => {
  const { setDisplayAlert, sharePointPath,  sharePointID, currentRacf, userProfile, setRefreshSharePointList, year} = props
  const [selectedFile, setSelectedFile] = useState()
  const [isUploading, setIsUploading] = useState(false)
  const [uploadProgress, setUploadProgress] = useState(0)
  const [currentFileName, setCurrentFileName] = useState("")
  const [currentIndex, setCurrentIndex] = useState(1)
  const [totalFiles, setTotalFiles] = useState(1)
  
  const handleFile = event => {
    setSelectedFile({ file: event.target.files })
  }

  const showUploadAlert = (uploadResult) => {
    let msg = "" 
    for (let i = 0; i < uploadResult.length; i += 1) {
        msg = msg.concat('\n\n', uploadResult[i].file, ' - ',uploadResult[i].reason ) 
    }
    if (msg.length > 0) {
      msg = "Following files cannot be uploaded : ".concat(msg) 
      alert (msg)
    }
  }

  const uploadChunkWithRetry = async (uploadUrl, chunk, chunkHeaders, maxRetries = 3) => {
    let attempt = 0;
    while (attempt < maxRetries) {
      try {
        return await axios.put(uploadUrl, chunk, { headers: chunkHeaders });
      } catch (error) {
        attempt++;
        if (attempt >= maxRetries) {
          throw error;
        }
        await new Promise(resolve => setTimeout(resolve, 1000 * attempt));
      }
    }
  }

  const handleUpload = async () => {
    if (!selectedFile || !selectedFile.file) return;
    const files = selectedFile.file      
    setTotalFiles(files.length)
    
    const options = {
      headers: {
        sharePointID : sharePointID,        
        'relative-url': sharePointPath.concat('/', currentRacf),
        name: userProfile.userName,
        office: userProfile.office,
      }
    }

    try {      
      let uploadResult = []
      setIsUploading(true)

      for (let i = 0; i < files.length; i++) {
        const file = files[i];
        setCurrentFileName(file.name);
        setCurrentIndex(i + 1);
        setUploadProgress(0);
        
        try {
          const sessionPayload = { filename: file.name };
          const sessionRes = await trackPromise(
            axios.post("/spoint/api/upload_session", sessionPayload, options), 
            "uploadSharePointx" 
          );
          
          const uploadUrl = sessionRes.data.uploadUrl;
          const chunkSize = 320 * 1024 * 10; 
          let start = 0;
          let itemId = null;

          while (start < file.size) {
            const end = Math.min(start + chunkSize, file.size);
            const chunk = file.slice(start, end);
            
            const chunkHeaders = {
              "Content-Range": `bytes ${start}-${end - 1}/${file.size}`
            };

            const uploadRes = await uploadChunkWithRetry(uploadUrl, chunk, chunkHeaders);
            
            if (uploadRes.status === 201 || uploadRes.status === 200) {
              itemId = uploadRes.data.id;
            }
            start = end;
            setUploadProgress(Math.round((start / file.size) * 100));
          }

          if (itemId) {
            const metaPayload = { item_id: itemId };
            await axios.post("/spoint/api/upload_metadata", metaPayload, options);
          }

          setDisplayAlert({ message: "Successfully uploaded " + file.name + " !!", position: 4, timeout: 10000, color: "alert__green" })
          
        } catch (error) {    
          const errMessage = error.response?.data?.error_message || error.message || "Upload failed"
          setDisplayAlert({ message: errMessage, position: 4, timeout: 10000, color: "alert__red" })
          uploadResult = uploadResult.concat({ file: file.name, status: "Failed", reason: errMessage })         
        }

        if (i < files.length - 1) {
          await new Promise(resolve => setTimeout(resolve, 800));
        }
      }      
      
      setRefreshSharePointList(x=>!x)
      showUploadAlert(uploadResult)
      document.getElementById("sharePoint_file").value = null  
      setSelectedFile(null)
 
    } catch (err) {
      setDisplayAlert({ message: "Unexpected upload error !!", position: 3, timeout: 10000, color: "alert__red" })    
      document.getElementById("sharePoint_file").value = null           
      setSelectedFile(null)
    } finally {
      setIsUploading(false)
      setUploadProgress(0)
      setCurrentFileName("")
      setCurrentIndex(1)
      setTotalFiles(1)
    }        
  }
 
  return (
    <Fragment>
      <div className="uploadDoc">
            {isUploading && (
              <div className="upload-progress-wrapper">
                <p className="upload-progress-text">
                  Uploading: {currentFileName} ({uploadProgress}%) - [File {currentIndex} of {totalFiles}]
                </p>
                <progress className="upload-progress-bar" value={uploadProgress} max="100"></progress>
              </div>
            )}
           <form>
            <input type="file" multiple name="file" id="sharePoint_file" onChange={handleFile} disabled={isUploading} />
            <button type="button" onClick={handleUpload} disabled={isUploading}>
              Upload Documents
            </button>
          </form>
       </div>
    </Fragment>
  )
}

export default UploadForm