import React, { Fragment } from "react"
 
const SharePoint = props => {
  const {currentRacf, sharePointPath,  sharePointID, year } = props

  
  const handleClick_view = () => {
    //https://macysinc.sharepoint.com/sites/MMGOverseas/2023Eleave/Forms/AllItems.aspx?dt=1671001816489&id=%2Fsites%2FMMGOverseas%2F2023ELeave%2FNF1VCC&FilterField1=SharePointID&FilterValue1=84829a80%2D6927%2D4aff%2Dba28%2D1feb7d7e64dc&FilterType1=Text&viewid=720379f5%2Deb23%2D410f%2D81d1%2Df4e43a1a1cab

    // sharePoint variables : sharePointPath, racf and office
    const url = "https://macysinc.sharepoint.com/sites/MMGOverseas/".concat(sharePointPath, "/Forms/AllItems.aspx?id=%2Fsites%2FMMGOverseas%2F", sharePointPath, "%2F", currentRacf, "%2F", "&FilterType1=Text&viewid=720379f5-eb23-410f-81d1-f4e43a1a1cab&FilterField1=SharePointID&FilterValue1=", sharePointID, "&dt=", new Date().getTime())
    
    console.log(url)

    var newWindow = window.open(url, "_blank", "noopener,noreferrer")
    if (newWindow) newWindow.opener = null
  }
  

  return (
    <Fragment>
      <div className="sharePoint_grid">
        <div className="sharePoint_cell">
          <img src="../static/img/sharePointx.jpg" alt="sharePoint" className="sharePoint_photo" />
        </div>
        <div></div>

        <div className="sharePoint_cell">
          Go to SharePoint&nbsp;
          <i
            className="fa  fa-sign-in clickable"
            onClick={() => {
              handleClick_view()
            }}
          ></i>
        </div>
        <div></div>     
      
        <div className="sharePoint_cell">
          SharePoint ID  : {sharePointID} &nbsp;&nbsp;          
        </div>
      </div>
    </Fragment>
  )
}
export default SharePoint
